sys_script.script:
(function executeRule(current, previous /* null when async */) {

    var direction = current.direction.toString();
    var integrationType = current.integration_type.toString();

    // Endpoint is required for every integration record.
    if (current.endpoint.nil()) {

        gs.addErrorMessage(
            'Endpoint is required for an Integration Log record.'
        );

        current.setAbortAction(true);
        return;
    }

    // REST API integrations must specify the HTTP method.
    if (
        integrationType == 'REST API' &&
        current.http_method.nil()
    ) {

        gs.addErrorMessage(
            'HTTP Method is required when Integration Type is REST API.'
        );

        current.setAbortAction(true);
        return;
    }

    // Outbound integrations must contain request data.
    if (
        direction == 'Outbound' &&
        current.request_data.nil()
    ) {

        gs.addErrorMessage(
            'Request Data is required for Outbound integrations.'
        );

        current.setAbortAction(true);
        return;
    }

    // Inbound integrations must contain response data.
    if (
        direction == 'Inbound' &&
        current.response_data.nil()
    ) {

        gs.addErrorMessage(
            'Response Data is required for Inbound integrations.'
        );

        current.setAbortAction(true);
        return;
    }

    // Bidirectional integrations require both request and response data.
    if (direction == 'Bidirectional') {

        if (current.request_data.nil()) {

            gs.addErrorMessage(
                'Request Data is required for Bidirectional integrations.'
            );

            current.setAbortAction(true);
            return;
        }

        if (current.response_data.nil()) {

            gs.addErrorMessage(
                'Response Data is required for Bidirectional integrations.'
            );

            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
